ALTER TABLE "OrderItem" ADD COLUMN "instructions" TEXT NOT NULL DEFAULT '';
CREATE TABLE "ModifierGroup" ("id" TEXT NOT NULL PRIMARY KEY, "businessId" TEXT NOT NULL, "name" TEXT NOT NULL, "minSelect" INTEGER NOT NULL DEFAULT 0, "maxSelect" INTEGER NOT NULL DEFAULT 1, "isActive" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "ModifierGroup_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ModifierGroup_businessId_idx" ON "ModifierGroup"("businessId");
CREATE TABLE "ModifierOption" ("id" TEXT NOT NULL PRIMARY KEY, "groupId" TEXT NOT NULL, "name" TEXT NOT NULL, "priceDeltaCents" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "ModifierOption_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "ModifierGroup" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ModifierOption_groupId_sortOrder_idx" ON "ModifierOption"("groupId", "sortOrder");
CREATE TABLE "ProductModifierGroup" ("productId" TEXT NOT NULL, "groupId" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("productId", "groupId"), CONSTRAINT "ProductModifierGroup_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ProductModifierGroup_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "ModifierGroup" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "OrderItemModifier" ("id" TEXT NOT NULL PRIMARY KEY, "orderItemId" TEXT NOT NULL, "optionId" TEXT, "groupName" TEXT NOT NULL, "optionName" TEXT NOT NULL, "priceDeltaCents" INTEGER NOT NULL, CONSTRAINT "OrderItemModifier_orderItemId_fkey" FOREIGN KEY ("orderItemId") REFERENCES "OrderItem" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "OrderItemModifier_optionId_fkey" FOREIGN KEY ("optionId") REFERENCES "ModifierOption" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "OrderItemModifier_orderItemId_idx" ON "OrderItemModifier"("orderItemId");
